1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Single home for how owners are grouped into a household and how a household's stable shared id is
9	 * derived. Parallels {@link OwnerIdentity} (the duplicate key) and {@link CustomerCode} (the
10	 * customer code): the create pipeline's {@link AssignOwnerHousehold} goes through here, so the
11	 * grouping rule and the id derivation stay defined in one place.
12	 *
13	 * <p>The household is keyed on {@code (normalizedLastName, postcode)}: two owners belong to the
14	 * same household exactly when they share a normalized last name and postcode. The
15	 * {@code householdId} is derived DETERMINISTICALLY from those same two fields (see
16	 * {@link #id(Owner)}), so owners with the same last name and postcode compute the identical value
17	 * automatically — there is no longer a stored value to reuse.
18	 */
19	final class Household {
20	
21	    private Household() {
22	    }
23	
24	    /** Comparison key for a last name: leading/trailing and repeated whitespace collapsed, lower-cased. */
25	    static String lastNameKey(String lastName) {
26	        if (lastName == null) {
27	            return "";
28	        }
29	        return lastName.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
30	    }
31	
32	    /** The postcode contribution to the household key: trimmed, or empty when absent. */
33	    private static String postcodeKey(String postcode) {
34	        return postcode == null ? "" : postcode.strip();
35	    }
36	
37	    /**
38	     * The household's stable shared identifier for {@code owner}, derived deterministically as the
39	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners
40	     * that share a normalized last name and postcode therefore compute the same value without any
41	     * coordination.
42	     */
43	    static String id(Owner owner) {
44	        return ShaHex.upperPrefix(lastNameKey(owner.getLastName()) + "|" + postcodeKey(owner.getPostcode()), 12);
45	    }
46	}
