3	import java.util.Locale;
4	import java.util.Objects;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Flags a soft duplicate. Runs after {@link CheckOwnerIdentityUnique} has already rejected hard
12	 * duplicates, so the owner reaching this step is not a hard duplicate. When an existing owner
13	 * shares the new owner's lastName (case-insensitive) and postcode but has a different telephone,
14	 * the new owner is still created but marked with {@link Owner#setPossibleDuplicate(boolean)} true
15	 * and {@link Owner#setPossibleDuplicateOf(Integer)} set to that owner's id. When more than one
16	 * existing owner matches, the one with the lowest id is chosen for a stable result. Otherwise
17	 * {@code possibleDuplicate} stays false and {@code possibleDuplicateOf} absent.
18	 *
19	 * <p>A declared household member ({@code sharesHousehold} true, which shares the new owner's
20	 * lastName and postcode) is deliberately NOT flagged: a declared member is not a suspected
21	 * duplicate.
22	 */
23	public class CheckOwnerPossibleDuplicate {
24	
25	    public void service(@Val Owner owner, @Val Boolean sharesHousehold,
26	            OwnerRepository ownerRepository) {
27	        if (Boolean.TRUE.equals(sharesHousehold)) {
28	            return; // a declared household member is not a suspected duplicate
29	        }
30	        String lastName = key(owner.getLastName());
31	        String postcode = owner.getPostcode();
32	        String telephone = owner.getTelephone();
33	        if (postcode == null || postcode.isBlank()) {
34	            return; // no postcode to match on
35	        }
36	        Owner match = null;
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (existing.getId() == null || existing.getId().equals(owner.getId())) {
39	                continue; // skip the owner being created
40	            }
41	            if (existing.isDeleted()) {
42	                continue; // a soft-deleted owner is not a soft-match either
43	            }
44	            if (!lastName.equals(key(existing.getLastName()))) {
45	                continue;
46	            }
47	            if (!postcode.equals(existing.getPostcode())) {
48	                continue;
49	            }
50	            if (Objects.equals(telephone, existing.getTelephone())) {
51	                continue; // same telephone is a hard duplicate territory, not a soft match
52	            }
53	            if (match == null || existing.getId() < match.getId()) {
54	                match = existing;
55	            }
56	        }
57	        if (match != null) {
58	            owner.setPossibleDuplicate(true);
59	            owner.setPossibleDuplicateOf(match.getId());
60	        }
61	    }
62	
63	    private static String key(String value) {
64	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
65	    }
66	}
