10	/**
11	 * Rejects an owner whose email domain is on the disposable-domain blocklist
12	 * (mailinator.com, tempmail.com, guerrillamail.com) with a 400. Email is optional,
13	 * so an absent address is a no-op. Runs on the built/applied {@link Owner} before it
14	 * is saved; the earlier {@code Build}/{@code Apply} step has already normalized the
15	 * address to a trimmed, lower-cased form, but the domain is lower-cased here too so
16	 * the check is robust regardless of ordering.
17	 */
18	public class CheckOwnerEmailDomain {
19	
20	    /** Email domains that are disposable and therefore not allowed. */
21	    private static final Set<String> DISPOSABLE_DOMAINS =
22	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
23	
